	@Test
	void testGetModelReportByDtxsid() throws Exception {
    		final List<Object> report = Collections.singletonList(modelReports);
		
		when(modelReportsRepository.findByDtxsid("DTXSID7020182")).thenReturn(report);
		
		mockMvc.perform(get("/chemical/property/model/reports/search/by-dtxsid/{dtxsid}", "DTXSID7020182"))
	  			.andDo(MockMvcResultHandlers.print())
	  			.andExpect(status().isOk())
	  			.andExpect(jsonPath("$[0].dtxsid").value(modelReports.getDtxsid()));
    }
	
	@Test
	void getJsonReportByDtxsidAndModelId() throws Exception {
		final String jsonString = jsonReport.getReportJson();
		
		when(modelReportsRepository.findReportJsonByDtxsidAndModelId("DTXSID7020182", 1163L)).thenReturn(jsonString);
		
		mockMvc.perform(get("/chemical/property/model/reports/json/search/")
				.param("dtxsid", "DTXSID7020182")
				.param("modelId", "1163"))
	  			.andDo(MockMvcResultHandlers.print())
	  			.andExpect(status().isOk())
	  			.andExpect(content().json(jsonReport.getReportJson()));
	}
	
	@Test
	void getHtmlReportByDtxsidAndModelId() throws Exception {
		final String htmlString = htmlReport.getReportHtml();
		
		when(modelReportsRepository.findReportHtmlByDtxsidAndModelId("DTXSID7020182", 1163L)).thenReturn(htmlString);
		
		mockMvc.perform(get("/chemical/property/model/reports/html/search/")
				.param("dtxsid", "DTXSID7020182")
				.param("modelId", "1163"))
	  			.andDo(MockMvcResultHandlers.print())
	  			.andExpect(status().isOk())
	  			.andExpect(content().string(htmlReport.getReportHtml()));
	}
	
	@Test
	void getModelFileByModelIdAndTypeId() throws Exception {
		final byte[] fileBytes = modelFiles.getFileBytes();
		
		when(modelFilesRepository.getFileForModelIdAndTTypeId(1161, 1)).thenReturn(fileBytes);
		
		mockMvc.perform(get("/chemical/property/model/file/search/")
				.param("modelId", "1161")
				.param("typeId", "1"))
	  			.andDo(MockMvcResultHandlers.print())
	  			.andExpect(status().isOk())
	  			.andExpect(content().bytes(fileBytes));
		
	}
	
